INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die Abnahme des Projekts ein zentraler Bestandteil der Abschlussphase?', 2, '[{"text": "Ja", "correct": true, "because": "Formalisiert Projektende"}, {"text": "Nein", "correct": false, "because": "Es gehört zum Abschluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Hauptziel hat die Projektabnahme?', 3, '[{"text": "Bestätigung der Zielerfüllung", "correct": true, "because": "Akzeptanz durch Stakeholder"}, {"text": "Neue Planung erstellen", "correct": false, "because": "Früherer Schritt"}, {"text": "Team neu organisieren", "correct": false, "because": "Anderer Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Abnahme prüft die Ergebnisse. b) Sie erfolgt während der Planung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Abschluss entscheidend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte werden bei der Projektabnahme überprüft?', 4, '[{"text": "Erfüllung der Anforderungen", "correct": true, "because": "Vergleicht mit Pflichtenheft"}, {"text": "Unklare Kriterien", "correct": false, "because": "Widerspricht Klarheit"}, {"text": "Qualität der Ergebnisse", "correct": true, "because": "Sichert Standards"}, {"text": "Funktionalität", "correct": true, "because": "Testet Umsetzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Projekt ohne Abnahme als abgeschlossen gelten?', 2, '[{"text": "Nein", "correct": true, "because": "Formale Zustimmung fehlt"}, {"text": "Ja", "correct": false, "because": "Unvollständig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Dokument hilft bei der Abnahme?', 3, '[{"text": "Abnahmeprotokoll", "correct": true, "because": "Dokumentiert Zustimmung"}, {"text": "Keine Dokumentation", "correct": false, "because": "Fehlt Nachweis"}, {"text": "Spontane Notizen", "correct": false, "because": "Unstrukturiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Abnahme nur für komplexe Projekte relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Projekte brauchen sie"}, {"text": "Ja", "correct": false, "because": "Breite Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die Abnahme im Projektmanagement?', 3, '[{"text": "Bestätigung des Projekterfolgs", "correct": true, "because": "Schließt Projekt ab"}, {"text": "Kosten neu kalkulieren", "correct": false, "because": "Controlling-Aspekt"}, {"text": "Zeitplan erstellen", "correct": false, "because": "Planungsaufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Abnahme basiert auf dem Pflichtenheft. b) Sie ist optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, essenziell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert ohne Abnahme des Projekts?', 3, '[{"text": "Ergebnisse bleiben unbestätigt", "correct": true, "because": "Keine Akzeptanz"}, {"text": "Projekt wird schneller", "correct": false, "because": "Unklarheit bleibt"}, {"text": "Kosten sinken", "correct": false, "because": "Risiko von Streit"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Abnahme ohne Abnahmekriterien erfolgen?', 2, '[{"text": "Nein", "correct": true, "because": "Maßstab fehlt"}, {"text": "Ja", "correct": false, "because": "Unklarer Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel zeigt eine Projektabnahme?', 3, '[{"text": "Kunde bestätigt App-Funktionalität", "correct": true, "because": "Konkret und formal"}, {"text": "Irgendwas übergeben", "correct": false, "because": "Zu vage"}, {"text": "Team sagt, es ist fertig", "correct": false, "because": "Keine Abnahme"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Abnahme nur für den Projektleiter wichtig?', 2, '[{"text": "Nein", "correct": true, "because": "Stakeholder sind entscheidend"}, {"text": "Ja", "correct": false, "because": "Projektweite Relevanz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte gehören zur Abnahme?', 4, '[{"text": "Prüfung der Ergebnisse", "correct": true, "because": "Bestätigt Erfüllung"}, {"text": "Unklare Zustimmung", "correct": false, "because": "Widerspricht Klarheit"}, {"text": "Abnahmeprotokoll erstellen", "correct": true, "because": "Dokumentiert"}, {"text": "Stakeholder-Befragung", "correct": true, "because": "Sichert Akzeptanz"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss die Abnahme schriftlich festgehalten werden?', 2, '[{"text": "Ja", "correct": true, "because": "Nachweis erforderlich"}, {"text": "Nein", "correct": false, "because": "Dokumentation wichtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode unterstützt die Abnahme?', 3, '[{"text": "Abnahmetestplan", "correct": true, "because": "Überprüft Ergebnisse"}, {"text": "Keine Prüfung", "correct": false, "because": "Fehlt Validierung"}, {"text": "Spontane Rückmeldung", "correct": false, "because": "Unstrukturiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Abnahme ohne Stakeholder erfolgen?', 2, '[{"text": "Nein", "correct": true, "because": "Zustimmung nötig"}, {"text": "Ja", "correct": false, "because": "Unvollständig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor erschwert die Abnahme?', 3, '[{"text": "Unklare Anforderungen", "correct": true, "because": "Verhindern Prüfung"}, {"text": "Klarer Testplan", "correct": false, "because": "Fördert Abnahme"}, {"text": "Gute Dokumentation", "correct": false, "because": "Unterstützt Prozess"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Abnahme bestätigt Vertragserfüllung. b) Sie ist nur für technische Projekte.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, breit anwendbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Nutzen der Projektabnahme?', 3, '[{"text": "Abschluss mit Stakeholder-Zufriedenheit", "correct": true, "because": "Bestätigt Erfolg"}, {"text": "Maximale Unklarheit", "correct": false, "because": "Widerspricht Zweck"}, {"text": "Keine Bestätigung", "correct": false, "because": "Fördert Klarheit"}]');